// Regenerated on every build run - do not edit by hand, do not commit.
// Mirrors the build flags documented in README.md:
//   MW_EXT_ENV            development | production (label only, affects logging verbosity)
//   MW_EXT_API_BASE_URL   backend base URL baked into the build
//   MW_EXT_STORE=1        store-distributable build: strips the declarativeNetRequest
//                         Referer helper so the artifact carries no DNR permission
//   MW_EXT_CHANNEL        dev | chrome | edge | site (distribution channel)
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const env = process.env.MW_EXT_ENV || process.env.NODE_ENV || "development";
const buildId = `${new Date().toISOString()}-${Math.random().toString(36).slice(2, 8)}`;
const apiBaseUrl = process.env.MW_EXT_API_BASE_URL || "https://mangowrite.com";
const storeBuild = process.env.MW_EXT_STORE === "1";
const storeDnrReferer = !storeBuild;
const channel = process.env.MW_EXT_CHANNEL || "dev";
// Distributed builds (any non-dev channel, or store builds) must not accept
// localhost/127.0.0.1 as a bridge origin - the postMessage bridge in
// src/bridge.ts is a second door besides the manifest's externally_connectable.
const allowDevOrigins = channel === "dev" && !storeBuild;

const outPath = fileURLToPath(new URL("../src/build-info.ts", import.meta.url));
const contents = `// AUTO-GENERATED by scripts/generate-build-info.mjs - do not edit by hand.
export const BUILD_ENV: string = ${JSON.stringify(env)};
export const BUILD_ID: string = ${JSON.stringify(buildId)};
export const API_BASE_URL: string = ${JSON.stringify(apiBaseUrl)};
export const STORE_DNR_REFERER: boolean = ${JSON.stringify(storeDnrReferer)};
export const BUILD_CHANNEL: string = ${JSON.stringify(channel)};
export const ALLOW_DEV_ORIGINS: boolean = ${JSON.stringify(allowDevOrigins)};
`;

writeFileSync(outPath, contents);
console.log(
  `[mangowrite-extension] wrote src/build-info.ts (env=${env}, apiBaseUrl=${apiBaseUrl}, storeDnrReferer=${storeDnrReferer}, channel=${channel}, allowDevOrigins=${allowDevOrigins})`
);
